"""Записать порученную программу 1/3/4; обучение этим шагом не запускается."""
from pathlib import Path
import sys, json
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.recovery_research_service_20261027 import RUN, read, write, sha, now
from scripts.b123_safe_journal_20261027 import journal

def main():
    ident='history_representations_factorial_v1'
    doc='dissertation/Проверка трёх представлений истории — отдельно и совместно.md'
    folder=RUN/'history_representations_program'
    assert not (folder/'program.json').exists(), 'Не регистрировать повторно'
    matrix=[[],[1],[3],[4],[1,3],[1,4],[3,4],[1,3,4]]
    program=dict(id=ident, created=now(), state='planned',
        author_request='Давай после этого прогона сделаем проверки с 1,3,4 представлением? По отдельности и слитно',
        definitions={'1':'Изображение истории движения','3':'Долговременная память внешнего вида','4':'Явная история реальных наблюдений'},
        matrix=matrix, seeds=[42,43,44], document=doc, after_current_b1_audit=True,
        primary_comparison='1+3+4 против общей базы и отдельно обученных последнего наблюдения/простого усреднения',
        readiness='Архитектуры, окна, разбиения и бюджеты фиксируются отдельным протоколом до обучения. Сейчас не готовы.',
        ready_for_training=False, training_started=False, hota_measured=False,
        hard_stop='2026-10-28T07:40:00+03:00',sha256={doc:sha(ROOT/doc)})
